 let line;
 if(axis==='x'||(axis==='g'&&y>=r.top&&y<=r.bottom))line={left:before?r.left-2:r.right-2,top:r.top,width:4,height:r.height};
 else line={left:r.left,top:before?r.top-2:r.bottom-2,width:r.width,height:4};
