function phMove(n,from,to){const l=String(n.bph||'').split('\n').filter(Boolean);if(from===to||from<0||to<0||from>=l.length||to>=l.length)return false;const x=l.splice(from,1)[0];l.splice(to,0,x);n.bph=l.join('\n');return true}
